package com.codeguardian.config; import lombok.Data; import org.springframework.boot.context.properties.ConfigurationProperties; import org.springframework.context.annotation.Configuration; import java.util.*;
@Data @Configuration @ConfigurationProperties(prefix="ai") public class AIConfigProperties {private String provider="QWEN";private Integer timeout=60;private Map<String,ProviderConfig> providers=new HashMap<>();@Data public static class ProviderConfig{private String baseUrl;private String apiKey;private String model;private Boolean enabled=true;} public ProviderConfig getProviderConfig(String name){return providers.get(name.toUpperCase());}}
